import{_ as o,o as a,c as i,a2 as n}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"El Principio de Retorno de Solo Conocimiento","description":"","frontmatter":{},"headers":[],"relativePath":"es/0087-仅回传知识原则.md","filePath":"es/0087-仅回传知识原则.md"}'),r={name:"es/0087-仅回传知识原则.md"};function t(s,e,c,d,l,u){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="el-principio-de-retorno-de-solo-conocimiento" tabindex="-1">El Principio de Retorno de Solo Conocimiento <a class="header-anchor" href="#el-principio-de-retorno-de-solo-conocimiento" aria-label="Permalink to &quot;El Principio de Retorno de Solo Conocimiento&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Elemento</th><th>Contenido</th></tr></thead><tbody><tr><td>N.º de documento</td><td>87</td></tr><tr><td>Módulo</td><td>Interacción Transplanar y Reglas Temporales</td></tr><tr><td>Palabras clave</td><td>retorno de solo conocimiento, purificación de la información, prohibición de retorno de materiales, codificación del conocimiento, auditoría de retorno</td></tr></tbody></table><h2 id="i-el-contexto-legislativo-y-el-concepto-central-del-principio" tabindex="-1">I. El Contexto Legislativo y el Concepto Central del Principio <a class="header-anchor" href="#i-el-contexto-legislativo-y-el-concepto-central-del-principio" aria-label="Permalink to &quot;I. El Contexto Legislativo y el Concepto Central del Principio&quot;">​</a></h2><p>El principio de &quot;retorno de solo conocimiento&quot; es uno de los principios fundamentales de la arqueología transplanar y de regresión temporal de la Civilización Simbiótica del Ancla, y su origen legal se remonta al artículo 48 de la Constitución Simbiótica: &quot;Ningún material, energía o ser vivo obtenido de otros planos u otros períodos de tiempo puede ser traído al propio plano sin permiso especial; el resultado legítimo de las actividades arqueológicas se limita al conocimiento e información abstractos.&quot; El establecimiento de este principio es una elección institucional realizada por el Universo Hengyuan tras resumir las dolorosas lecciones de la exploración transplanar temprana.</p><p>En los inicios del establecimiento de la Civilización Simbiótica del Ancla, la exploración transplanar se encontraba aún en un estado de desorden. Algunos exploradores trajeron al propio plano muestras materiales, cristales de energía e incluso seres vivos de otros planos para su investigación, desencadenando múltiples graves &quot;incidentes de contaminación transplanar&quot;. El caso más famoso es el &quot;Incidente del Cristal Extraño&quot;: un cristal de energía traído de un Plano de Manifestación de Energía, debido a la incompatibilidad de sus parámetros de leyes con el propio plano, desencadenó en la red de leyes del propio plano un desorden de las leyes que duró tres años, causando anomalías en los sistemas de cultivo de tres dominios estelares y dañando a decenas de miles de cultivadores en diversos grados. Las investigaciones posteriores demostraron que si en aquel momento se hubiera seguido el principio de &quot;retorno de solo conocimiento&quot;, esta catástrofe habría podido evitarse por completo.</p><p>El concepto central del principio de &quot;retorno de solo conocimiento&quot; es: el conocimiento es el único medio seguro en el intercambio entre civilizaciones. La materia y la energía portan la información de leyes de su plano de origen, y tras entrar en un entorno de leyes diferente pueden desencadenar reacciones impredecibles; mientras que el conocimiento, como información abstracta, puede, tras una codificación y purificación apropiadas, desprenderse de las huellas de leyes de su plano de origen y convertirse en un recurso seguro compartido entre planos.</p><h2 id="ii-la-definicion-y-clasificacion-del-conocimiento" tabindex="-1">II. La Definición y Clasificación del &quot;Conocimiento&quot; <a class="header-anchor" href="#ii-la-definicion-y-clasificacion-del-conocimiento" aria-label="Permalink to &quot;II. La Definición y Clasificación del &quot;Conocimiento&quot;&quot;">​</a></h2><p>En el marco legal del principio de &quot;retorno de solo conocimiento&quot;, el &quot;conocimiento&quot; tiene una definición y clasificación estrictas. No toda la información puede considerarse &quot;conocimiento&quot; y retornarse libremente — solo la información abstracta que ha pasado por el tratamiento de &quot;purificación de la información&quot; y de la que se ha confirmado que no porta ninguna contaminación de leyes cumple con el estándar de retorno.</p><p>El conocimiento se divide en tres categorías según su grado de abstracción y nivel de seguridad:</p><table tabindex="0"><thead><tr><th>Categoría de conocimiento</th><th>Definición</th><th>Nivel de seguridad</th><th>Requisito de retorno</th></tr></thead><tbody><tr><td>Conocimiento de nivel 1 (conocimiento puramente abstracto)</td><td>Conceptos abstractos, teoremas matemáticos, deducciones lógicas, ideas filosóficas, etc., completamente desvinculados de portadores materiales</td><td>El más alto (verde)</td><td>Puede retornarse directamente, sin aprobación especial</td></tr><tr><td>Conocimiento de nivel 2 (conocimiento descriptivo)</td><td>Información descriptiva sobre cosas objetivas, incluyendo registros históricos, datos geográficos, características biológicas, descripciones culturales, etc.</td><td>Medio (amarillo)</td><td>Debe pasar por el tratamiento de purificación de la información, retornado tras la aprobación de la Administración de Planos</td></tr><tr><td>Conocimiento de nivel 3 (conocimiento técnico)</td><td>Conocimiento práctico que contiene parámetros técnicos específicos, esquemas de ingeniería, métodos de cultivo</td><td>Más bajo (naranja)</td><td>Debe pasar por una estricta purificación de la información y evaluación de seguridad, retornado tras la aprobación especial de la Asamblea Legislativa del Ancla</td></tr></tbody></table><p>Los siguientes contenidos no pertenecen a la categoría de &quot;conocimiento&quot; y su retorno está estrictamente prohibido: muestras materiales de cualquier forma (incluyendo microorganismos, células, fragmentos de genes), cristales de energía o dispositivos de almacenamiento de energía de cualquier forma, seres vivos o entidades de conciencia que posean conciencia autónoma, datos brutos de cualquier forma que no hayan pasado por purificación de la información, y cualquier detalle técnico que pueda utilizarse para el cultivo depredador.</p><h2 id="iii-la-tecnologia-de-purificacion-de-la-informacion" tabindex="-1">III. La Tecnología de Purificación de la Información <a class="header-anchor" href="#iii-la-tecnologia-de-purificacion-de-la-informacion" aria-label="Permalink to &quot;III. La Tecnología de Purificación de la Información&quot;">​</a></h2><p>La purificación de la información es el eslabón técnico clave para garantizar la seguridad del conocimiento retornado. Su objetivo central es desprender por completo las huellas de leyes del plano de origen contenidas en la información bruta, conservando solo el contenido semántico puro. El proceso de purificación de la información se divide en cuatro pasos:</p><h3 id="_3-1-deconstruccion-de-la-informacion" tabindex="-1">3.1 Deconstrucción de la información <a class="header-anchor" href="#_3-1-deconstruccion-de-la-informacion" aria-label="Permalink to &quot;3.1 Deconstrucción de la información&quot;">​</a></h3><p>Primero, la información bruta a retornar se deconstruye estructuralmente, descomponiéndose en dos partes: el &quot;contenido semántico&quot; y la &quot;huella del portador&quot;. El contenido semántico es el significado abstracto que la información expresa; la huella del portador son los parámetros de leyes del plano de origen absorbidos por la información durante el almacenamiento y la transmisión. La deconstrucción de la información se realiza mediante el &quot;algoritmo de separación semántico-portador&quot;, que puede identificar y separar los componentes semánticos y los componentes de leyes en la información.</p><h3 id="_3-2-desprendimiento-de-leyes" tabindex="-1">3.2 Desprendimiento de leyes <a class="header-anchor" href="#_3-2-desprendimiento-de-leyes" aria-label="Permalink to &quot;3.2 Desprendimiento de leyes&quot;">​</a></h3><p>Se realiza un desprendimiento completo de leyes sobre la huella del portador separada. El método de desprendimiento consiste en hacer pasar la información por un &quot;canal de neutralización de leyes&quot; — un canal de transmisión especial cuyos parámetros de leyes están configurados como completamente neutros; al pasar la información, todos los parámetros de leyes no neutros que porta son absorbidos por las paredes del canal. Tras el desprendimiento de leyes, la información ya no porta ninguna huella de leyes del plano de origen.</p><h3 id="_3-3-reconstruccion-semantica" tabindex="-1">3.3 Reconstrucción semántica <a class="header-anchor" href="#_3-3-reconstruccion-semantica" aria-label="Permalink to &quot;3.3 Reconstrucción semántica&quot;">​</a></h3><p>Sobre la base del desprendimiento de leyes, el contenido semántico se recodifica, reconstruyendo la información con el sistema de codificación de información estándar del propio plano. La reconstrucción semántica garantiza que el conocimiento retornado pueda leerse y comprenderse correctamente en el entorno de leyes del propio plano, al tiempo que elimina además cualquier estructura de información del plano de origen que pueda subsistir.</p><h3 id="_3-4-deteccion-de-seguridad" tabindex="-1">3.4 Detección de seguridad <a class="header-anchor" href="#_3-4-deteccion-de-seguridad" aria-label="Permalink to &quot;3.4 Detección de seguridad&quot;">​</a></h3><p>La información purificada debe pasar por una estricta detección de seguridad, que incluye: la detección de residuos de leyes (confirmar que la información no porta ningún parámetro de leyes extraño), la detección de integridad semántica (confirmar que el proceso de purificación no ha alterado el contenido semántico de la información) y la evaluación de riesgos potenciales (evaluar los impactos sociales y de seguridad que el conocimiento puede traer al difundirse en el propio plano). Solo la información que supera las tres detecciones tiene permitido el retorno.</p><h2 id="iv-el-procedimiento-de-retorno-y-el-sistema-de-auditoria" tabindex="-1">IV. El Procedimiento de Retorno y el Sistema de Auditoría <a class="header-anchor" href="#iv-el-procedimiento-de-retorno-y-el-sistema-de-auditoria" aria-label="Permalink to &quot;IV. El Procedimiento de Retorno y el Sistema de Auditoría&quot;">​</a></h2><p>El retorno de conocimiento sigue una gestión procedimental estricta. Una operación de retorno completa incluye los siguientes eslabones:</p><ol><li><strong>Organización del conocimiento</strong>: el equipo arqueológico organiza los resultados de la investigación en documentos de conocimiento estandarizados, marcando claramente la categoría de conocimiento y el resumen del contenido.</li><li><strong>Solicitud de purificación</strong>: presentar una solicitud de purificación y retorno del conocimiento a la Administración de Planos o al Comité de las Leyes del Tiempo, adjuntando los documentos de conocimiento y los documentos de permiso de la misión arqueológica.</li><li><strong>Purificación de la información</strong>: un equipo técnico profesional de purificación de la información realiza el tratamiento de purificación de la información en cuatro pasos sobre los documentos de conocimiento.</li><li><strong>Detección de seguridad</strong>: el conocimiento purificado pasa por tres detecciones realizadas por una institución independiente de detección de seguridad.</li><li><strong>Retorno aprobado</strong>: tras superar las detecciones, la institución de aprobación firma el permiso de retorno, y el conocimiento se retorna a la base de conocimiento del propio plano a través del canal cifrado de la red del Ancla.</li><li><strong>Archivo en la base</strong>: el conocimiento retornado se registra oficialmente en la base tras la verificación por la base de conocimiento del propio plano, y se abre a los investigadores con los permisos correspondientes.</li></ol><p>Todas las operaciones de retorno deben pasar por una &quot;auditoría de retorno&quot;. El contenido de la auditoría incluye: si la fuente del conocimiento retornado es legítima, si el proceso de purificación es estándar, si la detección de seguridad es completa y si el procedimiento de aprobación es conforme. La auditoría está a cargo de la Oficina de Auditoría del Retorno de Conocimiento, dependiente del Comité de Supervisión del Ancla, que realiza cada trimestre inspecciones por muestreo de todas las operaciones de retorno del trimestre en curso y cada año una auditoría integral. Los resultados de la auditoría se informan a la Asamblea Legislativa del Ancla, y el resumen se divulga al público.</p><h2 id="v-violaciones-y-responsabilidad-legal" tabindex="-1">V. Violaciones y Responsabilidad Legal <a class="header-anchor" href="#v-violaciones-y-responsabilidad-legal" aria-label="Permalink to &quot;V. Violaciones y Responsabilidad Legal&quot;">​</a></h2><p>Los comportamientos que violan el principio de &quot;retorno de solo conocimiento&quot; incluyen: retornar sin aprobación información no purificada, disfrazar muestras materiales como conocimiento para retornarlas, ocultar deliberadamente en el conocimiento retornado las huellas de leyes del plano de origen, y ayudar a otros a realizar retornos ilegales.</p><p>Según la Constitución Simbiótica y la Ley de Gestión de Interacciones Transplanar, la responsabilidad legal de los comportamientos de retorno ilegal incluye: la confiscación de los objetos e información retornados ilegalmente, la suspensión o revocación de las calificaciones arqueológicas y de travesía de la parte implicada, multas de más de 10 veces el valor de los objetos retornados ilegalmente, prisión para los casos graves, y para los casos que causen contaminación de leyes o daños ecológicos, la asunción de todos los costos de restauración y la responsabilidad de indemnización.</p><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>El principio de &quot;retorno de solo conocimiento&quot; es la línea de sabiduría de la Civilización Simbiótica del Ancla en el campo de la interacción transplanar. Con definiciones estrictas, tecnología de purificación madura, procedimientos de retorno estandarizados y una severa responsabilidad legal, construye un sólido &quot;cortafuegos de seguridad del conocimiento&quot;. La importancia de este principio no reside solo en prevenir la contaminación a nivel físico, sino sobre todo en establecer una ética del intercambio entre civilizaciones: la interacción entre civilizaciones debe centrarse en el choque de ideas, no en el saqueo de materiales.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>84-考古协议总纲 (El Protocolo General de Arqueología)</li><li>88-跨位面伦理准则 (Las Normas Éticas Transplanar)</li><li>66-跨位面通讯技术 (La Tecnología de Comunicación Transplanar)</li></ul>',32)])])}const f=o(r,[["render",t]]);export{m as __pageData,f as default};
